package com.bank.fraud.scoring;

import java.math.BigDecimal;
import java.util.*;

// Fast feature lookups (Redis-like): per-account recent velocity + average amount.
public class FeatureStore {
    private final Map<String, Integer> recentCount = new HashMap<>();
    private final Map<String, BigDecimal> avgAmount = new HashMap<>();

    public void seed(String accountId, int count, BigDecimal avg) {
        recentCount.put(accountId, count);
        avgAmount.put(accountId, avg);
    }
    public int velocity(String accountId) { return recentCount.getOrDefault(accountId, 0); }
    public BigDecimal average(String accountId) { return avgAmount.getOrDefault(accountId, BigDecimal.ONE); }
    public void recordSwipe(String accountId) { recentCount.merge(accountId, 1, Integer::sum); }
}
