package com.bank.fraud.scoring;

import com.bank.fraud.model.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Stateful scoring with feature lookups + safer-but-slower bias + DLQ + idempotency.
public class FraudScorer {
    private static final Logger log = Logger.getLogger(FraudScorer.class.getName());
    private final FeatureStore features;
    private final int velocityThreshold;
    private final BigDecimal amountMultiplier;
    private final List<Transaction> deadLetterQueue = new ArrayList<>();
    private final Map<String, Decision> decided = new LinkedHashMap<>(); // idempotent by eventId

    public FraudScorer(FeatureStore features, int velocityThreshold, BigDecimal amountMultiplier) {
        this.features = features;
        this.velocityThreshold = velocityThreshold;
        this.amountMultiplier = amountMultiplier;
    }

    public Decision score(Transaction t) {
        // Idempotency: never decide the same event twice.
        if (decided.containsKey(t.getEventId())) {
            log.warning(() -> "Idempotent skip: " + t.getEventId() + " already decided");
            return decided.get(t.getEventId());
        }
        // Validation: poison → DLQ.
        if (t.getAmount() == null || t.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            deadLetterQueue.add(t);
            log.warning(() -> "DLQ: invalid event " + t.getEventId());
            return null;
        }
        // Feature lookups.
        int velocity = features.velocity(t.getAccountId());
        BigDecimal avg = features.average(t.getAccountId());
        features.recordSwipe(t.getAccountId());

        Decision d;
        if (t.getAmount().compareTo(avg.multiply(amountMultiplier)) > 0) {
            d = new Decision(t.getEventId(), Decision.Outcome.BLOCK,
                    "amount " + t.getAmount() + " > " + amountMultiplier + "x avg " + avg);
        } else if (velocity + 1 > velocityThreshold) {
            d = new Decision(t.getEventId(), Decision.Outcome.CHALLENGE,
                    "velocity " + (velocity + 1) + " > " + velocityThreshold + " (safer-but-slower)");
        } else {
            d = new Decision(t.getEventId(), Decision.Outcome.ALLOW, "within normal behaviour");
        }
        decided.put(t.getEventId(), d);
        log.info(() -> "DECISION " + t.getEventId() + " → " + d.getOutcome() + " (" + d.getReason() + ")");
        return d;
    }
    public int dlqSize() { return deadLetterQueue.size(); }
}
