package com.bank.fraud.storage;

import com.bank.fraud.model.*;
import java.util.*;
import java.util.logging.Logger;

// OLTP serving: post approved transactions; also mirror all decisions to analytics.
public class ServingStore {
    private static final Logger log = Logger.getLogger(ServingStore.class.getName());
    private final List<String> posted = new ArrayList<>();          // OLTP
    private final List<Decision> analyticsSink = new ArrayList<>(); // OLAP/lake copy

    public void apply(Transaction t, Decision d) {
        analyticsSink.add(d); // everything flows to analytics
        if (d.getOutcome() == Decision.Outcome.ALLOW) {
            posted.add(t.getEventId());
            log.info(() -> "OLTP posted approved txn " + t.getEventId());
        } else {
            log.info(() -> "Not posted (" + d.getOutcome() + ") " + t.getEventId());
        }
    }
    public int postedCount() { return posted.size(); }
    public int analyticsCount() { return analyticsSink.size(); }
}
