package com.bank.fraud;

import com.bank.fraud.model.*;
import com.bank.fraud.scoring.*;
import com.bank.fraud.storage.ServingStore;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class FraudPlatformDemo {
    private static final Logger log = Logger.getLogger(FraudPlatformDemo.class.getName());

    public static void main(String[] args) {
        FeatureStore features = new FeatureStore();
        features.seed("SAV2001", 0, new BigDecimal("2000"));  // Rajesh avg 2000
        features.seed("CUR3001", 3, new BigDecimal("4000"));  // Priya already at velocity 3

        FraudScorer scorer = new FraudScorer(features, 3, new BigDecimal("5"));
        ServingStore serving = new ServingStore();

        List<Transaction> stream = List.of(
            new Transaction("E1", "SAV2001", new BigDecimal("1500"), "Mumbai"),   // ALLOW
            new Transaction("E2", "SAV2001", new BigDecimal("20000"), "Mumbai"),  // BLOCK (>5x avg)
            new Transaction("E3", "CUR3001", new BigDecimal("3000"), "Delhi"),    // CHALLENGE (velocity)
            new Transaction("E4", "SAV2001", null, "Mumbai")                      // DLQ (poison)
        );

        log.info("=== Real-time scoring ===");
        for (Transaction t : stream) {
            Decision d = scorer.score(t);
            if (d != null) serving.apply(t, d);
        }

        log.info("=== Replay E2 (idempotent) ===");
        scorer.score(new Transaction("E2", "SAV2001", new BigDecimal("20000"), "Mumbai"));

        log.info("OLTP posted=" + serving.postedCount()
                + " analytics=" + serving.analyticsCount()
                + " dlq=" + scorer.dlqSize());
    }
}
